const now = new Date();
const yearStart = new Date(now.getFullYear(), 0, 1);
const yearEnd = new Date(now.getFullYear(), 11, 31);
const daysPassed = Math.floor((now - yearStart) / 86400000);
const daysTotal = Math.floor((yearEnd - yearStart) / 86400000);
const expectedPct = (daysPassed / daysTotal) * 100;

return input.map(dept => ({
  ...dept,
  expectedPct: Math.round(expectedPct * 10) / 10,
  overBudgetPct: Math.round((dept.spend_pct - expectedPct) * 10) / 10,
  projectedTotal: Math.round((dept.spent_amount / daysPassed) * daysTotal),
  severity: dept.spend_pct >= 100 ? 'critical' : dept.spend_pct >= 85 ? 'warning' : dept.spend_pct >= expectedPct * 1.1 ? 'watch' : 'healthy'
}));

config.body:
Dear {{dept.department}} Leadership,

This is an automated budget overspend alert.

Department: {{dept.department}}
Budget Allocated: ${{dept.allocated_amount}}
Amount Spent: ${{dept.spent_amount}} ({{dept.spend_pct}}%)
Remaining: ${{dept.remaining}}
Projected Year-End: ${{dept.projectedTotal}}

The department is {{dept.overBudgetPct}}% ahead of the expected spend rate for this point in the fiscal year.

Please review and submit a budget remediation plan within 5 business days.

Regards,
Finance Automation System
